export function generateCoreApiTypes(openApi, { generatedAt = new Date().toISOString() } = {}) {
  const routes = extractRoutes(openApi);
  const operationIds = [...new Set(routes.map((route) => route.operationId).filter(Boolean))].sort();
  const paths = [...new Set(routes.map((route) => route.path))].sort();
  const methods = [...new Set(routes.map((route) => route.method))].sort();
  return `// Generated by scripts/core-generate-client-types.mjs at ${generatedAt}.
// Do not edit by hand.

export type CoreApiMethod =
${unionLines(methods)};

export type CoreApiPath =
${unionLines(paths)};

export type CoreApiOperationId =
${unionLines(operationIds)};

export type CoreApiRouteKey = \`\${CoreApiMethod} \${CoreApiPath}\`;

export interface CoreApiRoute {
  readonly method: CoreApiMethod;
  readonly path: CoreApiPath;
  readonly operationId: CoreApiOperationId;
}

export declare const CORE_API_ROUTES: readonly CoreApiRoute[];
`;
}

export function extractRoutes(openApi) {
  return Object.entries(openApi?.paths ?? {})
    .flatMap(([path, methods]) => Object.entries(methods)
      .filter(([_method, operation]) => operation && typeof operation === 'object')
      .map(([method, operation]) => ({
        method: method.toUpperCase(),
        path,
        operationId: operation.operationId ?? `${method}_${path}`
      })))
    .sort((a, b) => `${a.path}:${a.method}`.localeCompare(`${b.path}:${b.method}`));
}

function unionLines(values) {
  if (!values.length) return '  never';
  return values.map((value) => `  | ${JSON.stringify(value)}`).join('\n');
}
